def det(rows,suffix='',prefix=''):
 return {'type':'determinant','rows':[[r'\('+str(v)+r'\)' for v in row] for row in rows],'suffix':suffix,'prefix':prefix,'caption':'Source concurrency determinant'}
BROWS=[['x_2-x_3','y_2-y_3',r'-\frac12(y_2^2-y_3^2)-\frac12(x_2^2-x_3^2)'],['x_3-x_1','y_3-y_1',r'-\frac12(y_3^2-y_1^2)-\frac12(x_3^2-x_1^2)'],['x_1-x_2','y_1-y_2',r'-\frac12(y_1^2-y_2^2)-\frac12(x_1^2-x_2^2)']]
AROWS=[['x_2-x_3','y_2-y_3','-x_1(x_2-x_3)-y_1(y_2-y_3)'],['x_3-x_1','y_3-y_1','-x_2(x_3-y_1)-y_2(y_3-y_1)'],['x_1-x_2','y_1-y_2','-x_3(x_1-x_2)-y_3(y_1-y_2)']]
def altitude_graph():
 a,b,c=(250,45),(100,270),(430,250)
 def foot(p,q,r):
  v=(r[0]-q[0],r[1]-q[1]);t=((p[0]-q[0])*v[0]+(p[1]-q[1])*v[1])/(v[0]**2+v[1]**2);return(q[0]+t*v[0],q[1]+t*v[1])
 d,e,f=foot(a,b,c),foot(b,a,c),foot(c,a,b)
 # Orthocenter from two normal-form altitude equations.
 u,v=(c[0]-b[0],c[1]-b[1]),(c[0]-a[0],c[1]-a[1]);s=u[0]*a[0]+u[1]*a[1];t=v[0]*b[0]+v[1]*b[1];den=u[0]*v[1]-u[1]*v[0];g=((s*v[1]-u[1]*t)/den,(u[0]*t-s*v[0])/den)
 return geometry('Figure 7.29','Figure 7.29 — three altitudes AD,BE,CF meeting at G',[path([a,b,c,a]),path([a,d]),path([b,e]),path([c,f])],[(245,30,'A'),(82,286,'B'),(435,265,'C'),(d[0]-8,d[1]+22,'D'),(e[0]+7,e[1],'E'),(f[0]-23,f[1],'F'),(g[0]+6,g[1]-5,'G')])
PAGES=[page('106_page_2.jpg',204,[eq(r'D\left(\frac{x_2+x_3}2,\frac{y_2+y_3}2\right),\quad E\left(\frac{x_1+x_3}2,\frac{y_1+y_3}2\right),\quad F\left(\frac{x_1+x_2}2,\frac{y_1+y_2}2\right)'),paragraph('If the slope of the side BC and the slope of the right bisector DG of the side BC are respectively:'),eq(r'm_1=\frac{y_3-y_2}{x_3-x_2},\quad m_2=-\frac1{m_1}=-\frac{x_3-x_2}{y_3-y_2}'),paragraph('then, the equation of the right bisector DG is obtained by point-slope form of a line:'),eq(r'\left(y-\frac{y_2+y_3}2\right)=-\frac{x_3-x_2}{y_3-y_2}\left(x-\frac{x_2+x_3}2\right)'),eq(r'(y_3-y_2)\left(y-\frac{y_2+y_3}2\right)=(x_2-x_3)\left(x-\frac{x_2+x_3}2\right)'),eq(r'x(x_2-x_3)+y(y_2-y_3)-\frac12(y_2^2-y_3^2)-\frac12(x_2^2-x_3^2)=0'),paragraph('Similarly, the equations of the right bisectors EG (of side CA), FG (of side AB) are respectively:'),eq(r'x(x_3-x_1)+y(y_3-y_1)-\frac12(y_3^2-y_1^2)-\frac12(x_3^2-x_1^2)=0'),eq(r'x(x_1-x_2)+y(y_1-y_2)-\frac12(y_1^2-y_2^2)-\frac12(x_1^2-x_2^2)=0'),paragraph('The right bisectors DG, EG and FG is concurrent, if the determinant of the coefficient matrix A of the related system of equations of the right bisectors DG, EG and FG equals zero:'),det(BROWS,'= 0 (i)'),paragraph('The operation of addition of rows R₁+R₂+R₃ to row R₁ is used to obtain:'),det([['0','0','0']]+BROWS[1:],'= 0 (ii)','∼'),paragraph('The value of the determinant is zero. Hence, the right bisectors DG, EG and FG of a triangle ABC are concurrent.'),note('For a nondegenerate triangle the first two side vectors are not parallel, so the corresponding bisectors have a unique finite intersection. Their three equation rows sum to zero, so that intersection also satisfies the third. This supplies the finite-point argument beyond determinant zero. Equivalently, the point equidistant from A and B and from B and C is also equidistant from A and C. The slope derivation divides by coordinate differences; its final dot-product equations remain valid for horizontal/vertical sides.'),heading('Example 25'),paragraph('Let ABC be a triangle with vertices A(0,0), B(8,6) and C(12,0). Show that the right bisectors DG, EG and FG of the triangle ABC are concurrent.'),heading('Solution'),paragraph('The vertices A(x₁,y₁) = A(0,0), B(x₂,y₂) = B(8,6) and C(x₃,y₃) = C(12,0) of the triangle ABC are used in the determinant (i) to obtain:')]),page('107_page_1.jpg',205,[det(BROWS,'= 0 ⇒'),det([[-4,6,22],[12,0,-72],[-8,-6,50]],'= 0'),eq(r'\Rightarrow\ -4(-432)-6(600-576)+22(-72)=0'),eq(r'\Rightarrow\ 1728-1728=0'),paragraph('The determinant (ii) equals zero. Hence, the right bisectors DG, EG and FG of the triangle ABC are concurrent.'),heading('ii. Three median of a triangle are concurrent'),paragraph('See topic 7.1.3 at page no 181.'),heading('iii. Three altitudes of a triangle are concurrent'),paragraph('Let ABC be a triangle, whose vertices are A(x₁,y₁), B(x₂,y₂) and C(x₃,y₃). The altitudes of the triangle ABC are AD, BE and CF.'),altitude_graph(),paragraph('If the slope of the side BC and the slope of the altitude AD are respectively'),eq(r'm_1=\frac{y_3-y_2}{x_3-x_2},\quad m_2=-\frac1{m_1}=-\frac{x_3-x_2}{y_3-y_2}'),paragraph('then, the equation of altitude AD is obtained by point-slope form of a line:'),eq(r'(y-y_1)=-\frac{x_3-x_2}{y_3-y_2}(x-x_1)'),eq(r'(y-y_1)(y_3-y_2)=(x_2-x_3)(x-x_1)x(x_2-x_3)+y(y_2-y_3)-x_1(x_2-x_3)-y_1(y_2-y_3)=0'),paragraph('Similarly, the equations of altitudes BE and CF are respectively:'),eq(r'x(x_3-x_1)+y(y_3-y_1)-x_2(x_3-x_1)-y_2(y_3-y_1)=0'),eq(r'x(x_1-x_2)+y(y_1-y_2)-x_3(x_1-x_2)-y_3(y_1-y_2)=0'),paragraph('The altitudes AD, BE and CF are concurrent, if the determinant of the coefficient matrix A of the related system of equations of the altitudes AD, BE and CF equals zero:'),det(AROWS,'= 0 (iii)'),paragraph('The operation of addition of rows R₁+R₂+R₃ to row R₁ is used to obtain:'),det([['0','0','0']]+AROWS[1:],'= 0','∼'),paragraph('The value of the determinant is zero. Therefore, the altitudes AD, BE and CF of a triangle ABC are concurrent at a point G.'),paragraph('The conclusion drawn from the above results is that the three medians AD, BE and CF of a triangle ABC will also make concurrency at a point say, G(x,y).'),note('The AD rearrangement joins two algebraic lines without a separator. Its intended two steps are (y−y₁)(y₃−y₂) = (x₂−x₃)(x−x₁), then x(x₂−x₃)+y(y₂−y₃)−x₁(x₂−x₃)−y₁(y₂−y₃) = 0. The source determinant’s second-row constant uses x₃−y₁, where x₃−x₁ is required; its zero-row operation is valid only after that correction. With correct rows, their sum is zero by cancellation of the pairwise dot products. In a nondegenerate triangle two altitude directions are not parallel, giving a unique finite orthocenter; the row dependency then puts it on the third altitude. Medians, internal angle bisectors, perpendicular bisectors and altitudes have their own concurrent centers—centroid, incenter, circumcenter and orthocenter—which are generally different even though the source reuses G.')])]
